<?php
declare(strict_types=1);
namespace App\Services;
use CodeIgniter\Database\BaseConnection;
use InvalidArgumentException;
final class WarehouseTransferService {
 private WarehouseStockService $stock;
 public function __construct(private ?BaseConnection $db=null){$this->db??=db_connect('default');$this->stock=new WarehouseStockService($this->db);}
 private function t(string $n):string{return $this->db->prefixTable($n);}
 private function decimal(mixed $v,string $label='Cantidad'):string{$v=str_replace(',','.',trim((string)$v));if(!preg_match('/^(?:0|[1-9]\d*)(?:\.\d{1,6})?$/',$v))throw new InvalidArgumentException($label.' debe ser decimal no negativo.');return bcadd($v,'0',6);}
 private function date(mixed $v):string{$v=str_replace('T',' ',trim((string)$v));if($v==='')return get_current_utc_time();$d=\DateTimeImmutable::createFromFormat('Y-m-d H:i',$v)?:\DateTimeImmutable::createFromFormat('Y-m-d H:i:s',$v);if(!$d)throw new InvalidArgumentException('La fecha no es válida.');return $d->format('Y-m-d H:i:s');}
 private function event(int $id,string $type,int $user,?string $notes=null,array $meta=[]):void{$this->db->table('warehouse_transfer_events')->insert(['warehouse_transfer_id'=>$id,'event_type'=>$type,'event_at'=>get_current_utc_time(),'user_id'=>$user?:null,'notes'=>$notes,'metadata_json'=>$meta?json_encode($meta,JSON_UNESCAPED_UNICODE):null]);}
 public function createDraft(array $in,int $user):int{$origin=(int)($in['origin_warehouse_id']??0);$destination=(int)($in['destination_warehouse_id']??0);if(!$origin||!$destination||$origin===$destination)throw new InvalidArgumentException('Seleccione almacenes de origen y destino distintos.');foreach([$origin,$destination] as $wid)if(!$this->db->table('warehouses')->where(['id'=>$wid,'status'=>'active','deleted'=>0])->countAllResults())throw new InvalidArgumentException('Seleccione almacenes activos.');$lines=[];foreach((array)($in['lines']??[]) as $line){$pid=(int)($line['warehouse_product_id']??0);$qty=$this->decimal($line['quantity_sent']??null);if(!$pid||bccomp($qty,'0',6)<=0)throw new InvalidArgumentException('Cada producto debe tener una cantidad mayor que cero.');if(!$this->db->table('warehouse_products')->where(['id'=>$pid,'status'=>'active','deleted'=>0])->countAllResults())throw new InvalidArgumentException('Seleccione productos de almacén activos.');if(isset($lines[$pid]))throw new InvalidArgumentException('No repita un producto en el mismo traspaso.');$lines[$pid]=['warehouse_product_id'=>$pid,'quantity_sent'=>$qty,'notes'=>trim((string)($line['notes']??''))?:null];}if(!$lines)throw new InvalidArgumentException('Agregue al menos un producto.');$now=get_current_utc_time();$this->db->transBegin();try{$this->db->table('warehouse_transfers')->insert(['folio'=>null,'origin_warehouse_id'=>$origin,'destination_warehouse_id'=>$destination,'transfer_date'=>$this->date($in['transfer_date']??''),'status'=>'draft','carrier'=>trim((string)($in['carrier']??''))?:null,'tracking_number'=>trim((string)($in['tracking_number']??''))?:null,'tracking_created_at'=>($in['tracking_number']??'')? $now:null,'estimated_arrival_at'=>($in['estimated_arrival_at']??'')?$this->date($in['estimated_arrival_at']):null,'reference_type'=>trim((string)($in['reference_type']??''))?:null,'reference_text'=>trim((string)($in['reference_text']??''))?:null,'notes'=>trim((string)($in['notes']??''))?:null,'created_by'=>$user?:null,'created_at'=>$now,'updated_at'=>$now,'deleted'=>0]);$id=(int)$this->db->insertID();$this->db->table('warehouse_transfers')->where('id',$id)->update(['folio'=>'TR-'.str_pad((string)$id,6,'0',STR_PAD_LEFT)]);foreach($lines as $line)$this->db->table('warehouse_transfer_lines')->insert(['warehouse_transfer_id'=>$id]+$line);$this->event($id,'created',$user);$this->db->transCommit();return $id;}catch(\Throwable $e){$this->db->transRollback();throw $e;}}
 public function dispatch(int $id,int $user):void{$this->db->transBegin();try{$tr=$this->db->query('SELECT * FROM '.$this->t('warehouse_transfers').' WHERE id=? FOR UPDATE',[$id])->getRow();if(!$tr)throw new InvalidArgumentException('El traspaso no existe.');if(in_array($tr->status,['in_transit','partially_received','received','received_with_difference'],true)){$this->db->transCommit();return;}if(!in_array($tr->status,['draft','prepared'],true))throw new InvalidArgumentException('El traspaso no puede despacharse en su estado actual.');$this->db->query('SELECT id FROM '.$this->t('warehouses').' WHERE id=? FOR UPDATE',[$tr->origin_warehouse_id]);$lines=$this->db->table('warehouse_transfer_lines')->where('warehouse_transfer_id',$id)->get()->getResult();if(!$lines)throw new InvalidArgumentException('El traspaso no contiene productos.');foreach($lines as $line){$available=$this->stock->getStock((int)$line->warehouse_product_id,(int)$tr->origin_warehouse_id);if(bccomp($available,(string)$line->quantity_sent,6)<0)throw new InvalidArgumentException('No existe cantidad suficiente en el almacén origen. Disponible: '.$available.'. Solicitado: '.$line->quantity_sent.'.');}$movement=$this->ledger('EXIT',(int)$tr->origin_warehouse_id,$tr->folio,$id,$lines,$user);$now=get_current_utc_time();$this->db->table('warehouse_transfers')->where('id',$id)->update(['status'=>'in_transit','dispatch_movement_id'=>$movement,'dispatched_at'=>$now,'updated_at'=>$now]);$this->event($id,'dispatched',$user,null,['movement_id'=>$movement]);$this->db->transCommit();}catch(\Throwable $e){$this->db->transRollback();throw $e;}}
 private function ledger(string $type,int $warehouse,string $folio,int $transferId,array $lines,int $user):int{$now=get_current_utc_time();$this->db->table('warehouse_movements')->insert(['folio'=>null,'movement_type'=>$type,'warehouse_id'=>$warehouse,'movement_date'=>$now,'reference_type'=>'WAREHOUSE_TRANSFER','reference_id'=>$transferId,'reference_text'=>$folio,'status'=>'confirmed','created_by'=>$user?:null,'confirmed_by'=>$user?:null,'confirmed_at'=>$now,'created_at'=>$now,'updated_at'=>$now]);$mid=(int)$this->db->insertID();$prefix=$type==='EXIT'?'SAL':'ENT';$this->db->table('warehouse_movements')->where('id',$mid)->update(['folio'=>$prefix.'-'.str_pad((string)$mid,6,'0',STR_PAD_LEFT)]);foreach($lines as $line){$qty=(string)($line->quantity_received??$line->quantity_sent);$this->db->table('warehouse_movement_lines')->insert(['warehouse_movement_id'=>$mid,'warehouse_product_id'=>$line->warehouse_product_id,'quantity'=>$qty,'quantity_delta'=>$type==='EXIT'?bcsub('0',$qty,6):$qty,'physical_quantity'=>null,'notes'=>'Traspaso '.$folio]);}return $mid;}
 public function receivedByLine(int $id):array{$rows=$this->db->query('SELECT tl.id,COALESCE(SUM(rl.quantity_received),0) received FROM '.$this->t('warehouse_transfer_lines').' tl LEFT JOIN '.$this->t('warehouse_transfer_receipt_lines').' rl ON rl.warehouse_transfer_line_id=tl.id WHERE tl.warehouse_transfer_id=? GROUP BY tl.id',[$id])->getResult();$out=[];foreach($rows as $r)$out[(int)$r->id]=bcadd((string)$r->received,'0',6);return $out;}
 public function receive(int $id,array $quantities,string $notes,int $user):int{$this->db->transBegin();try{$tr=$this->db->query('SELECT * FROM '.$this->t('warehouse_transfers').' WHERE id=? FOR UPDATE',[$id])->getRow();if(!$tr)throw new InvalidArgumentException('El traspaso no existe.');if(!in_array($tr->status,['in_transit','partially_received'],true))throw new InvalidArgumentException('El traspaso no está disponible para recepción.');$lines=$this->db->table('warehouse_transfer_lines')->where('warehouse_transfer_id',$id)->get()->getResult();$received=$this->receivedByLine($id);$nowLines=[];$any=false;foreach($lines as $line){$qty=$this->decimal($quantities[$line->id]??'0','Cantidad recibida');$pending=bcsub((string)$line->quantity_sent,$received[$line->id]??'0',6);if(bccomp($qty,$pending,6)>0)throw new InvalidArgumentException('No puede recibirse más de lo enviado. Pendiente: '.$pending.'.');if(bccomp($qty,'0',6)>0){$line->quantity_received=$qty;$nowLines[]=$line;$any=true;}}if(!$any)throw new InvalidArgumentException('Capture al menos una cantidad recibida.');$movement=$this->ledger('ENTRY',(int)$tr->destination_warehouse_id,$tr->folio,$id,$nowLines,$user);$now=get_current_utc_time();$this->db->table('warehouse_transfer_receipts')->insert(['warehouse_transfer_id'=>$id,'receipt_date'=>$now,'warehouse_movement_id'=>$movement,'notes'=>trim($notes)?:null,'created_by'=>$user?:null,'created_at'=>$now]);$receipt=(int)$this->db->insertID();foreach($nowLines as $line)$this->db->table('warehouse_transfer_receipt_lines')->insert(['warehouse_transfer_receipt_id'=>$receipt,'warehouse_transfer_line_id'=>$line->id,'warehouse_product_id'=>$line->warehouse_product_id,'quantity_received'=>$line->quantity_received]);$newReceived=$this->receivedByLine($id);$complete=true;foreach($lines as $line)if(bccomp($newReceived[$line->id]??'0',(string)$line->quantity_sent,6)<0){$complete=false;break;}$status=$complete?'received':'partially_received';$this->db->table('warehouse_transfers')->where('id',$id)->update(['status'=>$status,'received_at'=>$complete?$now:null,'updated_at'=>$now]);$this->event($id,$complete?'received':'partial_received',$user,$notes,['receipt_id'=>$receipt,'movement_id'=>$movement]);$this->db->transCommit();return $receipt;}catch(\Throwable $e){$this->db->transRollback();throw $e;}}
 public function closeWithDifference(int $id,string $reason,int $user):void{if(trim($reason)==='')throw new InvalidArgumentException('El motivo de la diferencia es obligatorio.');$this->db->transBegin();try{$tr=$this->db->query('SELECT * FROM '.$this->t('warehouse_transfers').' WHERE id=? FOR UPDATE',[$id])->getRow();if(!$tr||!in_array($tr->status,['in_transit','partially_received'],true))throw new InvalidArgumentException('El traspaso no puede cerrarse con diferencia.');$received=$this->receivedByLine($id);$lines=$this->db->table('warehouse_transfer_lines')->where('warehouse_transfer_id',$id)->get()->getResult();$count=0;foreach($lines as $line){$pending=bcsub((string)$line->quantity_sent,$received[$line->id]??'0',6);if(bccomp($pending,'0',6)>0){$this->db->table('warehouse_transfer_discrepancies')->insert(['warehouse_transfer_id'=>$id,'warehouse_transfer_line_id'=>$line->id,'warehouse_product_id'=>$line->warehouse_product_id,'quantity_difference'=>bcsub('0',$pending,6),'reason'=>trim($reason),'status'=>'reported','created_by'=>$user?:null,'created_at'=>get_current_utc_time()]);$count++;}}if(!$count)throw new InvalidArgumentException('No existe cantidad pendiente para registrar como diferencia.');$now=get_current_utc_time();$this->db->table('warehouse_transfers')->where('id',$id)->update(['status'=>'received_with_difference','received_at'=>$now,'updated_at'=>$now]);$this->event($id,'difference_reported',$user,$reason,['lines'=>$count]);$this->db->transCommit();}catch(\Throwable $e){$this->db->transRollback();throw $e;}}
 public function cancelDraft(int $id,int $user):void{$this->db->transBegin();try{$tr=$this->db->query('SELECT * FROM '.$this->t('warehouse_transfers').' WHERE id=? FOR UPDATE',[$id])->getRow();if(!$tr)throw new InvalidArgumentException('El traspaso no existe.');if($tr->status==='cancelled'){$this->db->transCommit();return;}if(!in_array($tr->status,['draft','prepared'],true))throw new InvalidArgumentException('Este traspaso ya fue despachado. Debe recibirse, devolverse o regularizarse mediante un movimiento trazable.');$now=get_current_utc_time();$this->db->table('warehouse_transfers')->where('id',$id)->update(['status'=>'cancelled','cancelled_at'=>$now,'cancelled_by'=>$user?:null,'updated_at'=>$now]);$this->event($id,'cancelled',$user);$this->db->transCommit();}catch(\Throwable $e){$this->db->transRollback();throw $e;}}
 public function updateLogistics(int $id,array $in,int $user):void{$tr=$this->db->table('warehouse_transfers')->where('id',$id)->get()->getRow();if(!$tr)throw new InvalidArgumentException('El traspaso no existe.');$data=['carrier'=>trim((string)($in['carrier']??''))?:null,'tracking_number'=>trim((string)($in['tracking_number']??''))?:null,'estimated_arrival_at'=>($in['estimated_arrival_at']??'')?$this->date($in['estimated_arrival_at']):null,'updated_at'=>get_current_utc_time()];if($data['tracking_number']&&!$tr->tracking_created_at)$data['tracking_created_at']=get_current_utc_time();if(!empty($in['picked_up']))$data['picked_up_at']=get_current_utc_time();$this->db->transBegin();try{$this->db->table('warehouse_transfers')->where('id',$id)->update($data);$this->event($id,!empty($in['picked_up'])?'picked_up':'tracking_added',$user,null,$data);$this->db->transCommit();}catch(\Throwable $e){$this->db->transRollback();throw $e;}}
 public function getInTransitStock(?int $productId=null):string{$sql='SELECT COALESCE(SUM(GREATEST(tl.quantity_sent-COALESCE(r.received,0)-COALESCE(d.closed_qty,0),0)),0) qty FROM '.$this->t('warehouse_transfer_lines').' tl JOIN '.$this->t('warehouse_transfers').' t ON t.id=tl.warehouse_transfer_id LEFT JOIN (SELECT warehouse_transfer_line_id,SUM(quantity_received) received FROM '.$this->t('warehouse_transfer_receipt_lines').' GROUP BY warehouse_transfer_line_id) r ON r.warehouse_transfer_line_id=tl.id LEFT JOIN (SELECT warehouse_transfer_line_id,SUM(ABS(quantity_difference)) closed_qty FROM '.$this->t('warehouse_transfer_discrepancies').' GROUP BY warehouse_transfer_line_id) d ON d.warehouse_transfer_line_id=tl.id WHERE t.status IN ("in_transit","partially_received")';$params=[];if($productId){$sql.=' AND tl.warehouse_product_id=?';$params[]=$productId;}$row=$this->db->query($sql,$params)->getRow();return bcadd((string)($row->qty??'0'),'0',6);}
}
